pub struct JitsiIntegration {
    pub base_url: String,
}

impl JitsiIntegration {
    pub fn new(base_url: &str) -> Self {
        Self {
            base_url: base_url.to_string(),
        }
    }

    pub fn generate_meeting_url(&self, meeting_id: &str) -> String {
        format!("{}/{}", self.base_url, meeting_id)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_generate_meeting_url() {
        let jitsi = JitsiIntegration::new("https://meet.jit.si");
        assert_eq!(jitsi.generate_meeting_url("test-meeting"), "https://meet.jit.si/test-meeting");
    }
}
